"use client"

import { useEffect, useState } from "react"
import Link from "next/link"

export default function Navbar() {
  const [isSticky, setIsSticky] = useState(false)

  useEffect(() => {
    const handleScroll = () => {
      setIsSticky(window.scrollY > 0)
    }

    window.addEventListener("scroll", handleScroll)
    return () => window.removeEventListener("scroll", handleScroll)
  }, [])

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id)
    element?.scrollIntoView({ behavior: "smooth" })
  }

  return (
    <nav className={`fixed w-full top-0 z-50 transition-shadow ${isSticky ? "shadow-lg" : ""} bg-[#000000]`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Left Side - Logo */}
          <div className="flex items-center gap-2">
            <Link href="/" className="text-white text-xl font-bold flex items-center gap-0.5">
              <span>G</span>
              <span>o</span>
              <span>al For A Cause</span>
            </Link>
          </div>

          {/* Right Side - Navigation Links */}
          <div className="flex gap-8">
            <button
              onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
              className="text-white hover:text-[#88C642] transition-colors text-sm font-medium"
            >
              About
            </button>
            <button
              onClick={() => scrollToSection("registration")}
              className="text-white hover:text-[#88C642] transition-colors text-sm font-medium"
            >
              Registration
            </button>
            <button
              onClick={() => scrollToSection("event-flow")}
              className="text-white hover:text-[#88C642] transition-colors text-sm font-medium"
            >
              Event Flow
            </button>
            <button
              onClick={() => scrollToSection("teams")}
              className="text-white hover:text-[#88C642] transition-colors text-sm font-medium"
            >
              Teams
            </button>
            <button
              onClick={() => scrollToSection("footer")}
              className="text-white hover:text-[#88C642] transition-colors text-sm font-medium"
            >
              Contact
            </button>
          </div>
        </div>
      </div>
    </nav>
  )
}
